    token=apis.file_system.login(username='susanmiller@gmail.com', password=pw)['access_token']

base_dir='~/photographs/vacations'
files=apis.file_system.show_directory(access_token=token, directory_path=base_dir+'/', entry_type='files', recursive=False)
year=datetime.datetime.now().year
mapping={'Athens':[], 'Seoul':[], 'Paris':[]}
file_info=[]
for f in files:
    info=apis.file_system.show_file(access_token=token, file_path=f)
    created=info.get('created_at')
    dt=datetime.datetime.fromisoformat(created)
    if dt.year==year and dt.month==1:
        spot='Athens'
    elif dt.year==year and dt.month==4:
        spot='Seoul'
    else:
        spot='Paris'
    mapping[spot].append(f)
    file_info.append((f, os.path.basename(f), spot, created))

for spot in ['Athens','Seoul','Paris']:
    print(spot, 'count', len(mapping[spot]))

# Build expected filename sets per spot
expected={spot:set(os.path.basename(p) for p in mapping[spot]) for spot in mapping}
print('expected_total', sum(len(s) for s in expected.values()))
print('unique_names_total', len(set().union(*expected.values())))
